      "notes_ja": [
        "Leica公式ブログはElmarを1926年から、公式レンズ用語集は1925年からと記載。年を確定せず資料差として残しています。",
        "1966年総合カタログ（冊子120頁）は、固定Elmar 50mm f/3.5を記すLeica Iを1925年からと掲載。ただしレンズ名別の切替年を分けていないため、1926年説を排除する決め手にはしません。",
        "追加確認：Leitz公式の当時広告の解説はElmarの導入を1925年10月と明記し、公式用語集・1966年カタログの1925年記述を補強します。ただし1926年とする公式掲載記事も残るため、資料差表示は維持します。",
        "追加追跡：文献経由で公開されたライツ従業員の手書き記録複写に、ElmaxからElmarへの名称変更の決定日「1925年10月7日」を確認しました。これは改名の証拠で、固定Elmar装着仕様の出荷開始を示す記録ではありません。「1925年発表・1926年発売」という区別で公式掲載記事の差を説明できる直接資料は見つからず、1925/26（資料差）を維持します。"
      ],
      "pending_ja": [
        "名称の変更決定と、固定Elmar装着仕様の最初の出荷・販売時期との関係は未確定です。",
        "寸法・重量、個体や製造時期ごとの細かな仕様差は未照合です。",
        "AI参考イラストと実物の一致は未検証です。"
      ],
